func TestRunGroupByReadsFromReadOnlyStore(t *testing.T) {
	dbPath := filepath.Join(t.TempDir(), "data.db")
	writer, err := store.Open(dbPath)
	if err != nil {
		t.Fatalf("open writer: %v", err)
	}
	items := []json.RawMessage{
		json.RawMessage(`{"id":"sub_1","email":"one@example.com","status":"active"}`),
		json.RawMessage(`{"id":"sub_2","email":"two@example.com","status":"inactive"}`),
		json.RawMessage(`{"id":"sub_3","email":"three@example.com","status":"active"}`),
	}
	if _, _, err := writer.UpsertBatch("subscribers", items); err != nil {
		t.Fatalf("seed subscribers: %v", err)
	}
	if err := writer.Close(); err != nil {
		t.Fatalf("close writer: %v", err)
	}

	reader, err := openStorePathForRead(dbPath)
	if err != nil {
		t.Fatalf("open read-only store: %v", err)
	}
	defer reader.Close()

	var out bytes.Buffer
	if err := runGroupBy(&out, reader, "subscribers", "status", 10, &rootFlags{asJSON: true}); err != nil {
		t.Fatalf("runGroupBy: %v", err)
	}

	var rows []struct {
		Value string `json:"value"`
		Count int    `json:"count"`
	}
	if err := json.Unmarshal(out.Bytes(), &rows); err != nil {
		t.Fatalf("group-by output must be JSON: %v\n%s", err, out.String())
	}
	if len(rows) != 2 {
		t.Fatalf("group-by row count = %d, want 2; output=%s", len(rows), out.String())
	}
	if rows[0].Value != "active" || rows[0].Count != 2 {
		t.Fatalf("top group = %+v, want active count 2; output=%s", rows[0], out.String())
	}
}
